// Check if 'data.txt' is readable/writable
// relative to a directory identified by 'dirfd'.
int dirfd = open("config_dir", O_RDONLY | O_DIRECTORY);
const char *file = "data.txt";
int result;

if (dirfd != -1) {
    result = faccessat(dirfd,
                       file,
                       R_OK | W_OK,
                       0); // Flags usually 0

    close(dirfd);
}

// Check existence relative to CWD, ignoring symlinks
result = faccessat(AT_FDCWD,
                   "link_file",
                   F_OK,
                   AT_SYMLINK_NOFOLLOW);

// Returns 0 on success (access granted)
if (result == -1) { /* Check errno */ }
